\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}

\title{Coastal Erosion and Dune Restoration on the North Norfolk Coast:\newline A Three-Year Survey of Foredune Recovery}
\author{P.~Nash and E.~Whittaker}
\date{May 2026}

\begin{document}
\maketitle

\begin{abstract}
Foredunes at three sites between Holkham and Blakeney were surveyed each spring from 2023 to 2025.
Aerial surveys mapped crest position and bare-sand patches at four-centimetre resolution.
Marram planting raised the mean crest height by 0.4~m at the most exposed site.
Sand fencing cut pedestrian trampling by half within one season.
\end{abstract}

\noindent\textbf{Keywords:} coastal erosion; dune restoration; UAV photogrammetry; sediment transport; vegetation succession

\section{Introduction}
Foredunes protect the grazing marshes behind the North Norfolk coast from storm surge.
The winter storms of 2020 and 2021 breached the dune line at two of the three study sites.
The National Trust asked for a baseline survey before committing to a planting programme.
This report summarises three years of survey work at the three sites.

\section{Findings}
Crest heights recovered fastest where marram planting followed the first winter.
The most exposed site gained 0.4~m of mean crest height over the three years.
Bare-sand patches shrank by two thirds at the sheltered site without any planting.
Trampling pressure fell by half where sand fencing guided visitors to signed crossings.

\end{document}
